/* RuleItem.insertItem */
INSERT INTO RULEITEM (
ITEMID
, ITEM_NM
, ITEMALIAS_NM
, ITEMEXPLAN_DESC
, DATATYPE_CD
, UPDATE_USERID
, UPDATE_DATETIME
, FIRSTREG_USERID
, FIRSTREG_DATETIME
, ITEM_USE_YN
, IFID
) VALUES (
#{itemId}
, #{itemNm}
, #{itemAliasNm}
, #{itemExplanDesc}
, #{dataTypeCd}
, NULL
, NULL
, #{firstRegUserId}
, TO_CHAR(CURRENT_TIMESTAMP, 'YYYYMMDDHH24MISS')
, #{itemUseYn}
, #{ifid}
)

mapper.update:
UPDATE RULEITEM
SET ITEM_NM         = #{itemNm}
, ITEMALIAS_NM    = #{itemAliasNm}
, ITEMEXPLAN_DESC = #{itemExplanDesc}
, DATATYPE_CD     = #{dataTypeCd}
, UPDATE_USERID   = #{updateUserID}
, UPDATE_DATETIME = TO_CHAR(CURRENT_TIMESTAMP, 'YYYYMMDDHH24MISS')
, ITEM_USE_YN     = #{itemUseYn}
, IFID            = #{ifid}
WHERE ITEMID = #{itemId}

